#define main regression_main
#include "test_core.c"
#undef main
static unsigned job_steps;
static int complete(IEJob*j){int result=0;unsigned limit=100000;CHECK(j);while(!result&&limit--){result=ie_job_step(j,37);++job_steps;}CHECK(limit);ie_job_destroy(j);return result;}
static unsigned selected(IEDoc*d){unsigned n=0;for(int y=0;y<d->current.height;y++)for(int x=0;x<d->current.width;x++)n+=ie_selection_alpha(&d->current,x,y)>0;return n;}
static IESelectionOptions rectangle(int x,int y,int xx,int yy){IESelectionOptions q={0};q.x0=x;q.y0=y;q.x1=xx;q.y1=yy;return q;}
static IEFillOptions fill_defaults(void){IEFillOptions q={0};q.kind=IE_FILL_SOLID;q.region=IE_FILL_SELECTION;q.opacity=q.density=100;q.scale=4;q.foreground=IE_RGBA(210,30,40,255);q.background=IE_RGBA(30,60,210,255);return q;}
static void selections(void){IEDoc d;Memory m;IESelectionOptions q;setup(&d,&m,17,13);q=rectangle(2,3,10,9);CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);CHECK(d.current.selection.x==2&&d.current.selection.w==9);q=rectangle(5,5,7,7);q.combine=IE_SELECT_SUBTRACT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==54);CHECK(!ie_selection_alpha(&d.current,6,6));q.combine=IE_SELECT_ADD;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);q.combine=IE_SELECT_INTERSECT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==9);q.method=IE_SELECT_INVERT;q.combine=0;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==17*13-9);
 q=rectangle(2,2,12,10);q.method=IE_SELECT_ELLIPSE;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_selection_alpha(&d.current,7,6)==255);CHECK(ie_selection_alpha(&d.current,2,2)==0);for(int y=2;y<=10;y++)for(int x=2;x<=12;x++)CHECK(ie_selection_alpha(&d.current,x,y)==ie_selection_alpha(&d.current,14-x,12-y));
 IEPoint points[]={{2,2},{12,2},{12,10},{7,6},{2,10}};q.method=IE_SELECT_LASSO;q.points=points;q.point_count=5;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_selection_alpha(&d.current,3,3)==255);CHECK(ie_selection_alpha(&d.current,7,9)==0);CHECK(ie_selection_alpha(&d.current,1,2)==0);CHECK(selected(&d)>40&&selected(&d)<90);IEPoint boundary[]={{0,0},{16,0},{16,12},{0,12}};q.points=boundary;q.point_count=4;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==17*13);IEPoint zigzag[2048];for(int i=0;i<2048;i++){zigzag[i].x=(i*7)%17;zigzag[i].y=i&1?12:0;}q.points=zigzag;q.point_count=2048;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)>0);
 q=rectangle(2,2,6,6);q.combine=IE_SELECT_INTERSECT;ie_select(&d,10,10,12,12);CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(d.current.selection.enabled&&selected(&d)==0);uint64_t before=digest(&d);IEFillOptions f=fill_defaults();CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==before&&d.undo_count==0);cleanup(&d,&m);
}
static void feather(void){IEDoc d;Memory m;setup(&d,&m,13,11);for(int radius=1;radius<=6;radius++){IESelectionOptions q=rectangle(0,2,8,8);q.feather=radius;CHECK(complete(ie_selection_start(&d,&q))==1);int k=2*radius+1;for(int y=0;y<11;y++)for(int x=0;x<13;x++){unsigned vertical=0;for(int yy=y-radius;yy<=y+radius;yy++){unsigned horizontal=0;int cy=yy<0?0:yy>10?10:yy;for(int xx=x-radius;xx<=x+radius;xx++){int cx=xx<0?0:xx>12?12:xx;horizontal+=(cx<=8&&cy>=2&&cy<=8)?255:0;}vertical+=(horizontal+k/2)/k;}CHECK(ie_selection_alpha(&d.current,x,y)==(vertical+k/2)/k);}}
 uint8_t mask[13*11];memcpy(mask,d.current.selection_mask,sizeof mask);uint64_t before=digest(&d);CHECK(ie_clear(&d));for(int y=0;y<11;y++)for(int x=0;x<13;x++)CHECK((ie_composite(&d,x,y)>>24)==255u-mask[y*13+x]);CHECK(ie_undo(&d));CHECK(digest(&d)==before&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_redo(&d));CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_undo(&d));CHECK(ie_transform(&d,100,100,0,0));CHECK(digest(&d)==before);CHECK(ie_undo(&d));CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));cleanup(&d,&m);}
static void floods(void){IEDoc d;Memory m;setup(&d,&m,9,7);for(int y=0;y<7;y++)d.current.layers[0].pixels[y*9+4]=0xff000000;IESelectionOptions q=rectangle(0,0,0,0);q.method=IE_SELECT_CONTIGUOUS;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==28);q.method=IE_SELECT_COLOR;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==56);q.method=IE_SELECT_CONTIGUOUS;q.tolerance=255;q.edge=40;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==28);q.edge=0;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);
 /* Random binary maps compared to an independent fixed-point reachability oracle. */
 unsigned state=817;for(int cycle=0;cycle<150;cycle++){unsigned char expected[63]={0};for(int i=0;i<63;i++){state=state*1664525u+1013904223u;d.current.layers[0].pixels[i]=state>>31?0xff000000:0xffffffff;}q.tolerance=0;q.x0=cycle%9;q.y0=cycle%7;expected[q.y0*9+q.x0]=1;int changed;do{changed=0;for(int y=0;y<7;y++)for(int x=0;x<9;x++){int i=y*9+x;if(!expected[i]&&d.current.layers[0].pixels[i]==d.current.layers[0].pixels[q.y0*9+q.x0]&&((x&&expected[i-1])||(x<8&&expected[i+1])||(y&&expected[i-9])||(y<6&&expected[i+9]))){expected[i]=1;changed=1;}}}while(changed);CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<63;i++)CHECK(!!ie_selection_alpha(&d.current,i%9,i/9)==expected[i]);}
 cleanup(&d,&m);
}
static void fills(void){IEDoc d;Memory m;setup(&d,&m,24,20);IEFillOptions f=fill_defaults();IESelectionOptions q=rectangle(4,4,17,15);q.method=IE_SELECT_ELLIPSE;q.feather=2;CHECK(complete(ie_selection_start(&d,&q))==1);uint8_t mask[480];memcpy(mask,d.current.selection_mask,sizeof mask);CHECK(ie_layer_add(&d,"Fill"));uint64_t empty=digest(&d);for(int kind=0;kind<=IE_FILL_DOTS;kind++){f.kind=kind;f.x=10;f.y=10;f.opacity=50;f.density=65;unsigned count=d.undo_count;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.undo_count==count+1);CHECK(digest(&d)!=empty);for(int i=0;i<480;i++){CHECK(d.current.layers[0].pixels[i]==0xffffffff);CHECK((d.current.layers[1].pixels[i]>>24)<=(mask[i]*50u+50)/100);if(!mask[i])CHECK(!d.current.layers[1].pixels[i]);}CHECK(ie_undo(&d));CHECK(digest(&d)==empty&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_redo(&d));CHECK(ie_undo(&d));}
 ie_deselect(&d);f=fill_defaults();f.kind=IE_FILL_LINEAR;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.current.layers[1].pixels[0]==f.foreground&&d.current.layers[1].pixels[23]==f.background);CHECK(ie_undo(&d));f.kind=IE_FILL_SOLID;f.region=IE_FILL_CONTIGUOUS;f.sample_merged=0;ie_select(&d,3,3,9,9);CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==empty);f.x=5;f.y=5;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.current.layers[1].pixels[5*24+5]==f.foreground);CHECK(d.current.layers[1].pixels[0]==0);cleanup(&d,&m);
}
static void rollback_and_oom(void){for(int type=0;type<3;type++)for(int failure=0;failure<12;failure++){IEDoc d;Memory m;setup(&d,&m,32,24);IESelectionOptions q=rectangle(4,4,20,18);q.feather=3;CHECK(complete(ie_selection_start(&d,&q))==1);uint8_t mask[768];memcpy(mask,d.current.selection_mask,sizeof mask);uint64_t before=digest(&d);size_t live=m.live;IEPoint points[]={{2,2},{28,4},{17,20}};q.method=type==0?IE_SELECT_CONTIGUOUS:IE_SELECT_LASSO;q.points=points;q.point_count=3;IEFillOptions f=fill_defaults();f.region=IE_FILL_CONTIGUOUS;f.feather=3;f.x=9;f.y=9;m.fail_at=m.calls+failure;m.persistent=1;IEJob*j=type==2?ie_fill_start(&d,&f):ie_selection_start(&d,&q);if(j){int result=0;while(!result)result=ie_job_step(j,37);if(result<0){CHECK(digest(&d)==before);CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));}ie_job_destroy(j);}else{CHECK(digest(&d)==before&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(m.live==live);}m.fail_at=-1;cleanup(&d,&m);}
 IEDoc d;Memory m;setup(&d,&m,80,60);CHECK(ie_adjust(&d,-20,0,0,100,100,100,0));CHECK(ie_undo(&d));d.dirty=0;uint64_t before=digest(&d);unsigned undo=d.undo_count,redo=d.redo_count;IEFillOptions f=fill_defaults();IEJob*j=ie_fill_start(&d,&f);CHECK(j);unsigned iterations=0;while(digest(&d)==before){CHECK(!ie_job_step(j,80));CHECK(++iterations<1000);}CHECK(d.gesture);ie_job_cancel(j);CHECK(digest(&d)==before&&d.undo_count==undo&&d.redo_count==redo&&!d.dirty);ie_job_destroy(j);CHECK(ie_redo(&d));cleanup(&d,&m);
 /* Reject a masked snapshot exceeding the explicit history cap before mutation. */
 setup(&d,&m,1800,1000);IESelectionOptions q=rectangle(1,1,1700,900);before=digest(&d);CHECK(!ie_selection_start(&d,&q));CHECK(digest(&d)==before&&!d.current.selection_mask&&d.history_bytes<=IE_HISTORY_MAX_BYTES);cleanup(&d,&m);setup(&d,&m,1000,1000);q=rectangle(2,2,900,900);CHECK(complete(ie_selection_start(&d,&q))==1);before=digest(&d);CHECK(!ie_layer_add(&d,"Too large with mask"));CHECK(digest(&d)==before&&d.current.count==1&&d.current.selection_mask);cleanup(&d,&m);
}
static void masked_move(void){IEDoc d;Memory m;setup(&d,&m,12,10);CHECK(ie_new(&d,12,10,0));d.current.layers[0].pixels[4*12+4]=0xff123456;IESelectionOptions q=rectangle(3,3,6,6);q.method=IE_SELECT_ELLIPSE;CHECK(complete(ie_selection_start(&d,&q))==1);uint64_t before=digest(&d);CHECK(ie_translate_selection(&d,3,2));CHECK(d.current.layers[0].pixels[6*12+7]==0xff123456);CHECK(d.current.layers[0].pixels[4*12+4]==0);CHECK(ie_undo(&d));CHECK(digest(&d)==before);uint16_t out[40];ie_render_selection_outline(&d,out,8,8,5,0,0,100,INT_MAX,INT_MAX,INT_MAX,INT_MAX);ie_render_selection_outline(&d,out,8,8,5,0,0,100,0,0,8,5);cleanup(&d,&m);}
int main(void){regression_main();selections();feather();floods();fills();rollback_and_oom();masked_move();printf("{\"checks\":%u,\"jobSteps\":%u,\"peakBytes\":%zu,\"randomFloodCases\":150,\"allocationFaultCases\":36,\"passed\":true}\n",checks,job_steps,peak_bytes);}
